/**
 * Chat moderation rules (SPEC 13 §8 "server-side moderation"): the offensive-word list, the strike ladder and the copy.
 * api2 runs them on every text before it is stored; the apps may run `findOffensive` to warn before sending, but the
 * server decides. Pure, zod-free and dependency-free.
 *
 * A hit refuses the message (422 `moderated`) and records a strike. Strikes count over STRIKE_WINDOW_DAYS; the
 * ladder mutes the sender for a while from the third one. Contact details and payment talk are not refused in chat
 * (arranging the job is fine): they only flag the message for the AI `chat.flag` review when Ops has it on.
 */

/** Words and phrases refused in chat (English and Filipino). Matched on whole words after `normalizeForMatch`. */
export const OFFENSIVE_TERMS: readonly string[] = [
  // English
  "fuck", "fucking", "fucker", "motherfucker", "fck", "fuk", "cunt", "bitch", "whore", "slut", "asshole", "dickhead",
  "bastard", "retard", "faggot", "fag", "nigger", "nigga", "kys", "kill yourself",
  // Filipino
  // (left out on purpose, they are everyday words here: "leche" as in leche flan, "puke", "gaga")
  "putang ina", "putangina", "tangina", "tang ina", "puta", "gago", "tarantado", "ulol", "inutil", "bobo", "tanga",
  "pakyu", "pokpok", "kantot", "hayop ka", "punyeta", "burat",
];

const LEET: Record<string, string> = { "0": "o", "1": "i", "3": "e", "4": "a", "5": "s", "7": "t", "@": "a", $: "s", "!": "i" };

/** Lower case, accents and look-alike digits folded, repeated letters squeezed ("fuuuck"), separators to one space. */
export function normalizeForMatch(text: string): string {
  return text
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[013457@$!]/g, (c) => LEET[c] ?? c)
    .replace(/([a-z])\1{2,}/g, "$1")
    .replace(/[^a-z]+/g, " ")
    .trim();
}

let compiled: RegExp | null = null;
function matcher(): RegExp {
  if (compiled) return compiled;
  const alts = [...new Set(OFFENSIVE_TERMS.map(normalizeForMatch))].sort((a, b) => b.length - a.length).map((t) => t.replace(/ /g, " ?"));
  compiled = new RegExp(`(?:^| )(${alts.join("|")})(?= |$)`, "g");
  return compiled;
}

/** The offensive terms in a text (normalised, each once), or [] when it is fine. */
export function findOffensive(text: string): string[] {
  const n = normalizeForMatch(text);
  if (!n) return [];
  const found = new Set<string>();
  for (const m of n.matchAll(matcher())) if (m[1]) found.add(m[1]);
  return [...found];
}

/** Strikes older than this no longer count. */
export const STRIKE_WINDOW_DAYS = 90;

/** The mute a strike number brings (hours), 0 for a warning. */
export function muteHoursFor(strikeNo: number): number {
  if (strikeNo <= 2) return 0;
  if (strikeNo === 3) return 24;
  if (strikeNo === 4) return 72;
  return 24 * 7;
}

export const MODERATED_MESSAGE = "Please keep it respectful. Your message was not sent.";

/** A text with contact details (phone, email, link, social handle) is refused before the insert (no strike). */
export const CONTACT_MESSAGE = "Contact details can't be sent in chat. Your message was not sent.";
/** The `body` field of that 422 `moderated`. */
export const CONTACT_LINE = "Remove the phone number, email, link or handle.";

/** The strike line under the composer (the `body` field of a 422 `moderated`). */
export function strikeLine(strikeNo: number): string {
  if (strikeNo === 1) return "This is a warning. After 3 warnings, you can't send messages for a while.";
  if (strikeNo === 2) return "This is your second warning. One more and you can't send messages for 24 hours.";
  const h = muteHoursFor(strikeNo);
  return h >= 24 * 7 ? "You can't send messages for 7 days." : h >= 72 ? "You can't send messages for 3 days." : "You can't send messages for 24 hours.";
}

/** The Ops mute presets (days). */
export const OPS_MUTE_DAYS = [1, 3, 7, 30] as const;
